//! Values derived from the CMU Pronouncing Dictionary (CMUdict, BSD-2-Clause-style; see NOTICE
//! and `style/data/licenses/cmudict.txt`). Only derived values are bundled, never phonemes.
//! Each table is generated by `scripts/build-cmudict.py` from one pinned `cmudict.dict`, so a
//! later table (initial sounds for alliteration, #307) is another output of the same script
//! with its own lookup here.

use std::collections::HashMap;
use std::sync::OnceLock;

const SYLLABLES: &str = include_str!("../data/pronunciation/cmudict-syllables.tsv");

fn syllable_table() -> &'static HashMap<&'static str, usize> {
    static TABLE: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    TABLE.get_or_init(|| {
        SYLLABLES
            .lines()
            .filter(|line| !line.starts_with('#'))
            .filter_map(|line| {
                let (word, count) = line.split_once('\t')?;
                Some((word, count.parse().ok()?))
            })
            .collect()
    })
}

/// CMUdict's syllable count (first pronunciation) for a key the heuristic in
/// [`crate::reports::readability::syllables`] gets wrong, or `None`. The table holds only those
/// exceptions: with it, every CMUdict headword gets CMUdict's count from
/// [`crate::reports::readability::syllables_with`]. A `None` therefore does not mean the word is
/// missing from CMUdict. Keys are lowercase with straight apostrophes and no leading or trailing
/// punctuation (`u.s`, `didn't`).
pub fn syllable_exception(key: &str) -> Option<usize> {
    syllable_table().get(key).copied()
}

/// Number of keys in the bundled syllable table.
pub fn syllable_exception_count() -> usize {
    syllable_table().len()
}
